    def letter?(character)
      codepoint = character.codepoints.first
      UNICODE_LETTER_RANGES.any? { |range| range[0] <= codepoint && codepoint <= range[1] }
    end

    def alpha?(character)
      codepoint = character.codepoints.first
      UNICODE_POSIX_ALPHA_RANGES.any? { |range| range[0] <= codepoint && codepoint <= range[1] }
    end

