    # rubocop:enable Layout/LineLength, Style/NumericLiterals
    def uncased_letter?(character)
      UNCASED_LETTER_RANGES.any? { |range| range.cover?(character.codepoints.first) }
    end

    def digit?(character)
      codepoint = character.codepoints.first
      UNICODE_POSIX_DIGIT_RANGES.any? { |range| range[0] <= codepoint && codepoint <= range[1] }
    end

    def xdigit?(character)
      codepoint = character.downcase.codepoints.first
      codepoint.between?("0".ord, "9".ord) || codepoint.between?("a".ord, "f".ord) ||
        codepoint.between?("A".ord, "F".ord)
    end

    def alnum?(character)
      alpha?(character) || digit?(character)
    end

    def lower?(character)
      codepoint = character.codepoints.first
      UNICODE_POSIX_LOWER_RANGES.any? { |range| range[0] <= codepoint && codepoint <= range[1] }
    end

    def upper?(character)
      codepoint = character.codepoints.first
      UNICODE_POSIX_UPPER_RANGES.any? { |range| range[0] <= codepoint && codepoint <= range[1] }
    end

    def caseable_letter?(character)
      letter?(character) && character.downcase != character.upcase
    end

    def space?(character)
      CharacterPredicates.whitespace?(character)
    end

    def word?(character)
      codepoint = character.codepoints.first
      UNICODE_POSIX_WORD_RANGES.any? { |range| range[0] <= codepoint && codepoint <= range[1] }
    end

    def blank?(character)
      CharacterPredicates.horizontal_whitespace?(character)
    end

    def cntrl?(character)
      codepoint = character.codepoints.first
      codepoint < 32 || codepoint.between?(0x7F, 0x9F)
    end

    def graph?(character)
      codepoint = character.codepoints.first
      !space?(character) && !cntrl?(character) &&
        UNICODE_POSIX_CN_RANGES.none? { |range| range[0] <= codepoint && codepoint <= range[1] }
    end

    def print?(character)
      codepoint = character.codepoints.first
      !cntrl?(character) && ![0x0A, 0x0B, 0x0C, 0x0D, 0x85, 0x2028, 0x2029].include?(codepoint) &&
        UNICODE_POSIX_CN_RANGES.none? { |range| range[0] <= codepoint && codepoint <= range[1] }
    end

    def unassigned?(character)
      codepoint = character.codepoints.first
      UNICODE_POSIX_CN_RANGES.any? { |range| range[0] <= codepoint && codepoint <= range[1] }
    end

    def punct?(character)
      codepoint = character.codepoints.first
      UNICODE_PUNCTUATION_RANGES.any? { |range| range[0] <= codepoint && codepoint <= range[1] }
    end

    def mark?(character)
      codepoint = character.codepoints.first
      UNICODE_MARK_RANGES.any? { |range| range[0] <= codepoint && codepoint <= range[1] }
    end

    def symbol?(character)
      codepoint = character.codepoints.first
      UNICODE_SYMBOL_RANGES.any? { |range| range[0] <= codepoint && codepoint <= range[1] }
    end

    def separator?(character)
      codepoint = character.codepoints.first
      UNICODE_SEPARATOR_RANGES.any? { |range| range[0] <= codepoint && codepoint <= range[1] }
    end

    def other?(character)
      !letter?(character) && !number?(character) && !mark?(character) && !separator?(character) &&
        !punct?(character) && !symbol?(character)
    end

    def numeric_symbol?(character)
      codepoint = character.codepoints.first
      codepoint.between?(0xB2, 0xB3) || codepoint == 0xB9 || codepoint.between?(0xBC, 0xBD) ||
        codepoint.between?(0xBF0, 0xBF2) || codepoint.between?(0x2070, 0x2079) ||
        codepoint.between?(0x2080, 0x2089) || codepoint.between?(0x2150, 0x2182) ||
        codepoint.between?(0x2460, 0x249B) || codepoint.between?(0x2776, 0x2793)
    end

    def number?(character)
      codepoint = character.codepoints.first
      UNICODE_NUMBER_RANGES.any? { |range| range[0] <= codepoint && codepoint <= range[1] }
    end

    def titlecase?(character)
      codepoint = character.codepoints.first
      UNICODE_TITLECASE_RANGES.any? { |range| range[0] <= codepoint && codepoint <= range[1] }
    end

    def modifier_letter?(character)
      codepoint = character.codepoints.first
      UNICODE_MODIFIER_LETTER_RANGES.any? { |range| range[0] <= codepoint && codepoint <= range[1] }
    end

    def other_letter?(character)
      codepoint = character.codepoints.first
      UNICODE_OTHER_LETTER_RANGES.any? { |range| range[0] <= codepoint && codepoint <= range[1] }
    end
  end
